import CloseIcon from '@jetbrains/icons/close.svg'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import Theme from '@jetbrains/ring-ui-built/components/global/theme'
import {H3} from '@jetbrains/ring-ui-built/components/heading/heading'
import Message from '@jetbrains/ring-ui-built/components/message/message'
import {Markdown} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import * as React from 'react'
import {Suspense} from 'react'

import {getAvailableHints} from '../Hints.selectors'
import type {HintPopupProps} from '../Hints.types'
import {stringifyHintId} from '../Hints.types'

import styles from './HintPopup.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

const DEFAULT_TAIL_OFFSET = 32

function Hint({
  id,
  currentIndex,
  total,
  btnPrevText,
  btnNextText,
  onClickPrev,
  onClickNext,
  onClose,
  dark = false,
  btnPrevPrimary = false,
}: HintPopupProps) {
  const availableHints = useAppSelector(getAvailableHints)
  const hint = availableHints.find(item => item.id === id)
  const popupProps = React.useMemo(() => {
    if (!hint) {
      return null
    }

    const anchorElement =
      typeof hint.selector === 'string'
        ? document.querySelector<HTMLElement>(hint.selector)
        : document.querySelector<HTMLElement>(`[data-hint-container-id=${stringifyHintId(id)}]`)
    return {
      anchorElement,
    }
  }, [hint, id])

  if (hint == null || popupProps?.anchorElement == null) {
    return null
  }

  const className = classNames(styles.popup, hint.className, hint.image && styles.withImage)
  return (
    <Message
      theme={dark ? Theme.DARK : Theme.LIGHT}
      className={className}
      directions={hint.directions}
      title={hint.image ? null : hint.name}
      key={stringifyHintId(hint.id)}
      icon={null}
      popupProps={popupProps}
      tailOffset={hint.offset ?? DEFAULT_TAIL_OFFSET}
    >
      {hint.image && <img className={styles.image} src={hint.image.src} alt={hint.image.alt} />}
      <div className={styles.content} data-hint-id={hint.id}>
        {hint.image && <H3 className={styles.title}>{hint.name}</H3>}
        <Suspense>
          <Markdown className={styles.description}>{hint.text}</Markdown>
        </Suspense>
        {(onClickPrev || onClickNext || (currentIndex && total)) && (
          <div className={styles.bot}>
            {onClickPrev && (
              <Button
                className={styles.btnPrev}
                onClick={onClickPrev}
                primary={btnPrevPrimary}
                data-hint-previous
              >
                {btnPrevText ?? 'Previous'}
              </Button>
            )}
            {onClickNext && (
              <Button onClick={onClickNext} primary={!btnPrevPrimary} data-hint-next>
                {btnNextText ?? 'Next'}
              </Button>
            )}
            {currentIndex && total && (
              <div className={styles.progress}>{`${currentIndex}/${total}`}</div>
            )}
          </div>
        )}
      </div>
      {onClose ? (
        <Button
          className={styles.btnClose}
          iconClassName={styles.closeIcon}
          icon={CloseIcon}
          onClick={onClose}
        />
      ) : null}
    </Message>
  )
}

export default React.memo(Hint)
